def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    bg = grid[0][0]

    # Find the solid divider column.
    div = next((c for c in range(w)
                if all(grid[r][c] == grid[0][c] for r in range(h))
                and grid[0][c] != bg), None)
    if div is None:
        return g
    divider_color = grid[0][div]

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != divider_color]
    if not cells:
        return g

    minc = min(c for r, c in cells)
    maxc = max(c for r, c in cells)

    # Move the object toward the divider until its bounding box is one
    # cell away, then draw a vertical marker just beyond its far edge.
    if maxc < div:
        shift = div - 1 - maxc
    elif minc > div:
        shift = div + 1 - minc
    else:
        shift = 0

    obj = [(r, c, grid[r][c]) for r, c in cells]
    for r, c, color in obj:
        g[r][c] = bg
    for r, c, color in obj:
        nc = c + shift
        if 0 <= nc < w:
            g[r][nc] = color

    moved_min = minc + shift
    moved_max = maxc + shift
    mark = moved_min - 1 if moved_max < div else moved_max + 1
    if 0 <= mark < w:
        for r in range(h):
            if g[r][mark] == bg:
                g[r][mark] = 8
    return g
